INSERT INTO "producer" ("id", "user_id", "nip", "name", "country_code", "rating", "review_count", "technology", "verification_status", "created_at", "updated_at", "deleted_at", "production_scale", "inquiry_response_time_label", "showroom_visit_available", "showroom_visit_note", "description", "communication_locale") VALUES ('2ac7718c-4ff6-567c-a8bb-3eeaaca3d612', 'catalog-import:lifepolska', '6462323947', 'Life Polska', 'PL', NULL, 0, NULL, 'not_submitted', '2026-11-11T10:16:01.717Z'::timestamptz, '2026-11-11T10:37:13.779Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Polski producent saun ogrodowych i balii z Górnego Śląska. Sauny powstają z selekcjonowanego drewna świerkowego, cedru syberyjskiego lub modrzewia modyfikowanego termicznie, z własnym piecem Diabaz ładowanym od zewnątrz i autorskim, wodoodpornym połączeniem belek ścian. Wszystkie urządzenia można sterować smartfonem przez Wi-Fi, a gotowe produkty producent dostarcza własnym transportem w całej Europie.', 'pl') ON CONFLICT DO NOTHING;
