INSERT INTO "producer_member" ("id", "producer_id", "user_id", "added_by", "created_at") VALUES ('9d4cf969-722c-43b8-93c6-0a8fa7e8d5eb', '2ac7718c-4ff6-567c-a8bb-3eeaaca3d612', 'catalog-import:lifepolska', NULL, '2026-11-11T10:16:01.717Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('b0072ce3-1668-40ba-ba59-abb2826b8a16', '2ac7718c-4ff6-567c-a8bb-3eeaaca3d612', 'en', 'Polish producer of garden saunas and hot tubs from Upper Silesia. The saunas are built from selected spruce, Siberian cedar or thermally modified larch, with the in-house Diabaz stove that is fed from the outside and a proprietary, waterproof wall beam joint. All devices can be controlled from a smartphone over Wi-Fi, and the producer delivers finished products with its own transport across Europe.', NULL, NULL, '2026-11-11T10:16:01.717Z'::timestamptz, '2026-11-11T10:16:01.717Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('aa7db650-cba6-44ae-970f-2f02393c0446', '2ac7718c-4ff6-567c-a8bb-3eeaaca3d612', 'de', 'Polnischer Hersteller von Gartensaunen und Badefässern aus Oberschlesien. Die Saunen entstehen aus ausgewähltem Fichtenholz, sibirischer Zeder oder thermisch modifizierter Lärche, mit dem hauseigenen, von außen beschickten Ofen Diabaz und einer eigenen, wasserdichten Verbindung der Wandbalken. Alle Geräte lassen sich per Smartphone über WLAN steuern, und die fertigen Produkte liefert der Hersteller mit eigenem Transport in ganz Europa.', NULL, NULL, '2026-11-11T10:16:01.717Z'::timestamptz, '2026-11-11T10:16:01.717Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('00166bce-fe37-4c06-a325-1ffeedb22f91', '2ac7718c-4ff6-567c-a8bb-3eeaaca3d612', 'nl', 'Poolse producent van tuinsauna''s en hottubs uit Boven-Silezië. De sauna''s worden gebouwd van geselecteerd vurenhout, Siberische ceder of thermisch gemodificeerd lariks, met de eigen Diabaz-kachel die van buitenaf wordt gestookt en een eigen waterdichte verbinding van de wandbalken. Alle apparaten zijn via wifi met een smartphone te bedienen, en de producent levert de afgewerkte producten met eigen transport in heel Europa.', NULL, NULL, '2026-11-11T10:16:01.717Z'::timestamptz, '2026-11-11T10:16:01.717Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "reference_text_translation" ("id", "source_pl", "locale", "translated", "created_at", "updated_at") VALUES ('33be979a-b0ed-4124-8269-83ffeb1e78f6', 'Producent krajowy, dostawa gotowego produktu', 'nl', 'Binnenlandse producent, levering van een kant-en-klaar product', '2026-11-11T10:16:01.717Z'::timestamptz, '2026-11-11T10:16:01.717Z'::timestamptz) ON CONFLICT DO NOTHING;
